eventScripts.script:

debug = system.tag.read("[.]debug").value
log = system.util.getLogger('lotTrackerUDT')
if debug: log.info('tag change script triggered')

if not initialChange and currentValue.quality.isGood() and previousValue.quality.isGood() and currentValue.value != previousValue.value and (currentValue.value or None) is not None:
	if debug: log.info('lotTracker change with lotName %s'%currentValue.value)
	userId = system.kanoa.security.getIDPUserId({'userName': "SYSTEM"})

	# get key tag values
	lotName = currentValue.value.strip()
	tagPaths = ["[.]lotOperationName", "[.]itemName", "[.]assetId"]
	tagData = system.tag.readBlocking(tagPaths)
	lotOperationName = tagData[0].value
	itemName = tagData[1].value
	assetId = tagData[2].value

	if (lotOperationName or None) is None: 
		msg = 'Invalid lot operation'
		log.error(msg)
		system.tag.write("[.]message", msg)
		return

	if assetId is None: 
		msg = 'Invalid assetId'
		log.error(msg)
		system.tag.write("[.]message", msg)			
		return

	if (lotName or None) is None or lotName == 'null' : 
		msg = 'Invalid lotName'
		log.error(msg)
		system.tag.write("[.]message", msg)			
		return

	# construct lot operation event			
	lotOperationId = system.kanoa.utilities.getFieldValue('lotOperationId', system.kanoa.lot.getLotOperations({'lotOperationName': lotOperationName}))
	if lotOperationId is None:
		lotOperationInfo = {'lotOperationName': lotOperationName, 'lotOperationColor': None, 'allowInputLots': True, 'allowOutputLots': True, 'enabled': True}
		lotOperationId, msg = system.kanoa.lot.addLotOperation(lotOperationInfo, userId)			
		if msg: 
			msg = 'Could not create lot operation named %s. %s'%(lotOperationName, msg)
			log.error(msg)
			system.tag.write("[.]message", msg)				
			return

	lotOperationEventInfo = {'lotOperationEventId': None, 'lotOperationId': lotOperationId, 'assetId': assetId, 'tStamp': system.date.now(), 'enabled': True}
	if debug: log.info('constructed lot operation event info %s'%lotOperationEventInfo)

	# if this lot name already exists, use that lot; otherwise make a new one
	if debug: log.info('looking for lot name %s'%lotName)
	lotInfo = system.kanoa.utilities.convertDatasetRowToJSON(system.kanoa.lot.getLots({'lotName': lotName}), 0)
	if lotInfo['lotId'] is None:
		if (itemName or None) is None: 
			msg = 'Invalid itemName. Canot create new lot'
			log.error(msg)
			system.tag.write("[.]message", msg)
			return
		lotInfo = {'lotName': lotName, 'itemId': system.kanoa.utilities.getFieldValue('itemId', system.kanoa.item.getItems({'itemName': itemName})), 'itemUnitId': system.kanoa.utilities.getFieldValue('itemUnitId', system.kanoa.item.getItemUnits({'itemUnitName': 'units'}))}
		if debug: log.info('lot not found, making lot with info %s'%lotInfo)
		lotId, msg = system.kanoa.lot.addLot(lotInfo, userId)
		if msg: 
			msg = 'Could not create lot named %s. %s'%(lotName, msg)
			log.error(msg)
			system.tag.write("[.]message", msg)
			return			

	# grab any lot events associated with this lot
	# if you don't find any; keep our inputLotEvent set to None and we'll create the new lot event from scratch
	# if you do find one; get the most recent and copy over its appropriate properties to the new output lot event; and save it for use as the inputLotEvent in executeLotOperation
	itemSources = system.kanoa.utilities.convertDatasetToDict(system.kanoa.item.getItemSource({'enabled': True}), 'itemSourceName', 'itemSourceId')
	okLotStateId = system.kanoa.utilities.getFieldValue('lotStateId', system.kanoa.lot.getLotStates({'lotStateName': "OK"}))

	lastLotEventInfo = system.kanoa.utilities.convertDatasetRowToJSON(system.kanoa.lot.getLotEvents({'lotId': lotInfo['lotId'], 'itemSourceId': itemSources['output'], 'getLastEvent': True}), 0)
	if lastLotEventInfo['lotEventId'] is None:
		inputLotEvents = []
	else:
		if debug: log.info('found last lot event %s'%lastLotEventInfo)
		inputLotEventInfo = dict(lastLotEventInfo)			
		inputLotEventInfo['lotEventId'] = None
		inputLotEventInfo['itemSourceId'] = itemSources['input']
		inputLotEventInfo['tStamp'] = system.date.now()
		inputLotEvents = [inputLotEventInfo]

	outputLotEventInfo = dict(inputLotEventInfo)
	if debug: log.info("outputLotEventInfo was %s"%(outputLotEventInfo))		
	outputLotEventInfo['lotEventId'] = None
	outputLotEventInfo['assetId'] = assetId
	outputLotEventInfo['itemSourceId'] = itemSources['output']
	outputLotEventInfo['tStamp'] = system.date.now()			

	# set up all of our lot event and operation event info for execution
	if debug: log.info('Calling executeLotOperation() with %s'%(lotOperationEventInfo))
	if debug: log.info('inputLotEventInfo() %s'%(inputLotEventInfo))
	if debug: log.info("outputLotEventInfo['assetId'] %s"%(outputLotEventInfo['assetId']))
	records, msg = system.kanoa.lot.executeLotOperation(lotOperationEventInfo, inputLotEvents, [outputLotEventInfo], userId)

	if msg is not None: 
		log.error(msg)
		system.tag.write("[.]message", msg)
	else:
		if debug: log.info('success')
		system.tag.write("[.]message", 'success')

	return


if currentValue.value:
	try:
		paramsDict = {'startDate': system.date.addWeeks(system.date.now(), -4), 'endDate': system.date.addWeeks(system.date.now(), 4), 'ignoreActualQty': True, 'workOrderStatusList': ['Released', 'Scheduled', 'In Progress']}
		system.tag.write("[.]WOData", system.kanoa.order.getProductionOrders(paramsDict))
		system.tag.write("[.]lastUpdated", system.date.now())
	except:
		log = system.util.getLogger('kanoa')
		log.error("ProductionSchedule tag - updateWOData() tag script failed")

	import time
	time.sleep(0.5)

	system.tag.write("[.]updateWOData", 0)


if system.tag.read("[.]enabled").value:
	system.tag.write("[.]update", True)

return

if currentValue.value:

	import java.lang
	log = system.util.getLogger('kanoa_tag')
	tagValues = system.tag.readBlocking(["[.]debug", "[.]updateTrigger"])
	debug = tagValues[0].value
	updateTriggerTime = tagValues[1].value
	errorMsg = ''
	timeNow = system.date.now()

	try:
		pass	#execute some function here
	except java.lang.Exception, e:
		errorMsg = e.cause
	except:
		errorMsg = 'unknown error'

	import time
	time.sleep(0.5)	#in case tag is being triggered manually, the change will be visible to the person

	if errorMsg: log.warn("%s timer script failed with %s"%(tagPath, errorMsg))
	system.tag.writeBlocking(["[.]lastUpdated", "[.]update", "[.]error"], [updateTriggerTime, 0, errorMsg])
	if debug: log.info("%s update took %sms"%(tagPath, system.date.millisBetween(timeNow, system.date.now())))

return
